\[ U_\mathrm{A}=U_0-I_\mathrm{D} R_\mathrm{D}=U_0-\left( g_\mathrm{m} U_\mathrm{GS} +I_\mathrm{DSS}\right) R_\mathrm{D}
\]
\[ U_\mathrm{A}=U_0-I_\mathrm{DSS} R_\mathrm{D} -g_\mathrm{m} R_\mathrm{D} \frac{R_2}{R_1 + R_2} U_\mathrm{E}
\]
\[ U_\mathrm{A}(0)=U_0-I_\mathrm{DSS} R_\mathrm{D} = 6\mathrm{V}
\]
\[ U_\mathrm{A}(50\mathrm{mV})=5,6\mathrm{V}
\]
\[ v=\dfrac{\mathrm{d}U_\mathrm{A}}{\mathrm{d}U_\mathrm{E}}=-g_\mathrm{m} R_\mathrm{D} \frac{R_2}{R_1 + R_2}=-8
\]
